You'll need to replace `YOUR_API_KEY` with your actual API key and `YOUR_CSE_ID` with your actual CSE ID.
*/
var apikey = 'YOUR_API_KEY';
var cseid = 'YOUR_CSE_ID';
var searchInput = document.getElementById('search-input');
var searchSuggestions = document.getElementById('search-suggestions');

searchInput.addEventListener('input', function(event) {
  var query = event.target.value;
  if (query.length > 2) {
    var xhr = new XMLHttpRequest();
    xhr.open('GET', `https://www.googleapis.com/customsearch/v1?q=${query}&key=${apikey}&cx=${cseid}`, true);
    xhr.onload = function() {
      if (xhr.status === 200) {
        var results = JSON.parse(xhr.responseText).items;
        var suggestionList = '';
        for (var i = 0; i < results.length; i++) {
          suggestionList += '<li>' + results[i].title + '</li>';
        }
        searchSuggestions.innerHTML = suggestionList;
      }
    };
    xhr.send();
  } else {
    searchSuggestions.innerHTML = '';
  }
});

searchSuggestions.addEventListener('click', function(event) {
  var suggestedQuery = event.target.textContent;
  searchInput.value = suggestedQuery;
});
